extras.new_content:
/// Peeks the next lexer token if any, but transposes it for convenience.
fn peek(&mut self) -> Result<Option<&Token>> {
    match self.lexer.peek() {
        Some(Ok(t)) => Ok(Some(t)),
        Some(Err(_)) => Err(errinput!("lexer error")),
        None => Ok(None),
    }
}
